void TrajectorySplineSmoother::optimize_trajectory(
  TrajectoryPoints & traj_points, const TrajectoryOptimizerParams & params,
  TrajectoryOptimizerData & data)
{
  if (!params.use_akima_spline_interpolation) {
    return;
  }
  trajectory_spline_smoother_utils::apply_spline(
    traj_points, spline_params_.interpolation_resolution_m,
    spline_params_.max_distance_discrepancy_m,
    spline_params_.preserve_input_trajectory_orientation);
  // TODO(Daniel): The spline should recalculate time_from_start based on the new trajectory points
  // and the current vehicle position. This is necessary to ensure that the time_from_start values
  // are consistent with the new trajectory. For now, we will use the motion_utils function.
  autoware::motion_utils::calculate_time_from_start(
    traj_points, data.current_odometry.pose.pose.position);
}

void apply_spline(
  TrajectoryPoints & traj_points, const double interpolation_resolution_m,
  const double max_distance_discrepancy_m, const bool preserve_original_orientation)
{
  constexpr size_t minimum_points_for_akima_spline = 5;
  if (traj_points.size() < minimum_points_for_akima_spline) {
    auto clock = rclcpp::Clock::make_shared(RCL_ROS_TIME);
    RCLCPP_WARN_THROTTLE(
      rclcpp::get_logger("trajectory_spline_smoother"), *clock, 5000,
      "Not enough points in trajectory for spline interpolation");
    return;
  }
  const TrajectoryPoints original_traj_points = traj_points;
  auto trajectory_interpolation_util =
    InterpolationTrajectory::Builder{}
      .set_xy_interpolator<AkimaSpline>()  // Set interpolator for x-y plane
      .build(traj_points);
  if (!trajectory_interpolation_util) {
    auto clock = rclcpp::Clock::make_shared(RCL_ROS_TIME);
    RCLCPP_WARN_THROTTLE(
      rclcpp::get_logger("trajectory_spline_smoother"), *clock, 5000,
      "Failed to build interpolation trajectory");
    return;
  }
  trajectory_interpolation_util->align_orientation_with_trajectory_direction();
  constexpr double min_interpolation_step = 1e-2;
  const auto ds = std::max(interpolation_resolution_m, min_interpolation_step);

  TrajectoryPoints output_points{};
  output_points.reserve(static_cast<size_t>(1 + trajectory_interpolation_util->length() / ds));
  double last_s{0.0};
  for (auto s = 0.0; s <= trajectory_interpolation_util->length(); s += ds) {
    auto p = trajectory_interpolation_util->compute(s);
    if (!autoware::trajectory_optimizer::utils::validate_point(p)) {
      continue;
    }
    output_points.push_back(p);
    last_s = s;
  }

  if (trajectory_interpolation_util->length() - last_s > min_interpolation_step) {
    output_points.push_back(
      trajectory_interpolation_util->compute(trajectory_interpolation_util->length()));
  }

  if (output_points.size() < 2) {
    auto clock = rclcpp::Clock::make_shared(RCL_ROS_TIME);
    RCLCPP_WARN_THROTTLE(
      rclcpp::get_logger("trajectory_spline_smoother"), *clock, 5000,
      "Not enough points in trajectory after akima spline interpolation");
    return;
  }

  if (preserve_original_orientation) {
    autoware::trajectory_optimizer::utils::copy_trajectory_orientation(
      original_traj_points, output_points, max_distance_discrepancy_m, M_PI);
  }

  traj_points = output_points;
}

void Trajectory<PointType>::align_orientation_with_trajectory_direction()
{
  if (bases_.size() < 2) {
    // Not enough points to determine trajectory direction, so we skip alignment.
    return;
  }
  std::vector<geometry_msgs::msg::Quaternion> aligned_orientations;
  for (const auto & s : bases_) {
    const double azimuth = this->azimuth(s);
    const double elevation = this->elevation(s);
    const geometry_msgs::msg::Quaternion current_orientation =
      orientation_interpolator_->compute(s);
    tf2::Quaternion current_orientation_tf2(
      current_orientation.x, current_orientation.y, current_orientation.z, current_orientation.w);
    current_orientation_tf2.normalize();

    // Calculate the current x-axis of the orientation (local x-axis)
    const tf2::Vector3 current_x_axis =
      tf2::quatRotate(current_orientation_tf2, tf2::Vector3(1, 0, 0));

    // Calculate the desired x-axis direction based on the trajectory's azimuth and elevation
    const tf2::Vector3 desired_x_axis(
      std::cos(elevation) * std::cos(azimuth), std::cos(elevation) * std::sin(azimuth),
      std::sin(elevation));

    const double dot_product =
      std::clamp(current_x_axis.dot(desired_x_axis), -1.0, 1.0);  // Clamp to avoid NaN
    const double rotation_angle = std::acos(dot_product);

    const tf2::Vector3 rotation_axis = [&]() {
      // If the rotation angle is nearly 0 or 180 degrees, choose a default rotation axis
      if (std::abs(rotation_angle) < 1e-6 || std::abs(rotation_angle - M_PI) < 1e-6) {
        // Use the rotated z-axis as the fallback axis
        return tf2::quatRotate(current_orientation_tf2, tf2::Vector3(0, 0, 1));
      }
      // Otherwise, compute the rotation axis using the cross product of the current and desired
      // x-axes
      tf2::Vector3 cross = current_x_axis.cross(desired_x_axis);
      return cross.normalized();
    }();

    // Create a quaternion representing the rotation required to align the x-axis
    tf2::Quaternion delta_q = tf2::Quaternion(rotation_axis, rotation_angle);

    // Apply the rotation delta to the current orientation and normalize the result
    const tf2::Quaternion aligned_orientation_tf2 =
      (delta_q * current_orientation_tf2).normalized();

    geometry_msgs::msg::Quaternion aligned_orientation;
    aligned_orientation.x = aligned_orientation_tf2.x();
    aligned_orientation.y = aligned_orientation_tf2.y();
    aligned_orientation.z = aligned_orientation_tf2.z();
    aligned_orientation.w = aligned_orientation_tf2.w();

    aligned_orientations.emplace_back(aligned_orientation);
  }
  const auto success = orientation_interpolator_->build(bases_, std::move(aligned_orientations));
  assert(
    success &&
    "Trajectory<Pose>::align_orientation_with_trajectory_direction: failed to build "
    "orientation interpolator");
}

double Trajectory<PointType>::azimuth(const double s) const
{
  const auto s_clamp = clamp(s, true);
  const double dx = x_interpolator_->compute_first_derivative(s_clamp);
  const double dy = y_interpolator_->compute_first_derivative(s_clamp);
  return std::atan2(dy, dx);
}

double compute_first_derivative(const double s) const
{
  const double clamped_s = this->validate_compute_input(s);
  return compute_first_derivative_impl(clamped_s);
}

double validate_compute_input(const double s) const
{
  constexpr double eps = 1e-5;
  if (eps < start() - s || s - end() > eps) {
    RCLCPP_WARN(
      rclcpp::get_logger("Interpolator"),
      "Input value %f is outside the range of the interpolator [%f, %f].", s, start(), end());
  }
  return std::clamp(s, start(), end());
}

double Pchip::compute_first_derivative_impl(const double s) const
{
  const int32_t i = this->get_index(s);
  const double dx = s - this->bases_.at(i);
  return b_(i) + 2.0 * c_(i) * dx + 3.0 * d_(i) * dx * dx;
}

int32_t get_index(const double s, bool end_inclusive = true) const
{
  if (end_inclusive && s == end()) {
    return static_cast<int32_t>(bases_.size()) - 2;
  }
  auto comp = [](const double & a, const double & b) { return a <= b; };
  const auto distance =
    std::distance(bases_.begin(), std::lower_bound(bases_.begin(), bases_.end(), s, comp));
  const int32_t idx = (distance == 0) ? 0 : static_cast<int32_t>(distance) - 1;
  return std::clamp(idx, static_cast<int32_t>(0), static_cast<int32_t>(bases_.size() - 1));
}

double compute_first_derivative(const double s) const
{
  const double clamped_s = this->validate_compute_input(s);
  return compute_first_derivative_impl(clamped_s);
}

double validate_compute_input(const double s) const
{
  constexpr double eps = 1e-5;
  if (eps < start() - s || s - end() > eps) {
    RCLCPP_WARN(
