      "Input value %f is outside the range of the interpolator [%f, %f].", s, start(), end());
  }
  return std::clamp(s, start(), end());
}

double Pchip::compute_first_derivative_impl(const double s) const
{
  const int32_t i = this->get_index(s);
  const double dx = s - this->bases_.at(i);
  return b_(i) + 2.0 * c_(i) * dx + 3.0 * d_(i) * dx * dx;
}

int32_t get_index(const double s, bool end_inclusive = true) const
{
  if (end_inclusive && s == end()) {
    return static_cast<int32_t>(bases_.size()) - 2;
  }
  auto comp = [](const double & a, const double & b) { return a <= b; };
  const auto distance =
    std::distance(bases_.begin(), std::lower_bound(bases_.begin(), bases_.end(), s, comp));
  const int32_t idx = (distance == 0) ? 0 : static_cast<int32_t>(distance) - 1;
  return std::clamp(idx, static_cast<int32_t>(0), static_cast<int32_t>(bases_.size() - 1));
}

PointType Trajectory<PointType>::compute(const double s) const
{
  PointType result;
  result.pose = Trajectory<geometry_msgs::msg::Pose>::compute(s);
  const auto s_clamp = clamp(s);
  result.longitudinal_velocity_mps =
    static_cast<float>(this->longitudinal_velocity_mps().compute(s_clamp));
  result.lateral_velocity_mps = static_cast<float>(this->lateral_velocity_mps().compute(s_clamp));
  result.heading_rate_rps = static_cast<float>(this->heading_rate_rps().compute(s_clamp));
  result.acceleration_mps2 = static_cast<float>(this->acceleration_mps2().compute(s_clamp));
  result.front_wheel_angle_rad = static_cast<float>(this->front_wheel_angle_rad().compute(s_clamp));
  result.rear_wheel_angle_rad = static_cast<float>(this->rear_wheel_angle_rad().compute(s_clamp));
  return result;
}

bool validate_point(const TrajectoryPoint & point)
{
  auto is_valid = [](auto value) { return std::isfinite(value) && !std::isnan(value); };

  return is_valid(point.longitudinal_velocity_mps) && is_valid(point.acceleration_mps2) &&
         is_valid(point.pose.position.x) && is_valid(point.pose.position.y) &&
         is_valid(point.pose.position.z) && is_valid(point.pose.orientation.x) &&
         is_valid(point.pose.orientation.y) && is_valid(point.pose.orientation.z) &&
         is_valid(point.pose.orientation.w);
}

void copy_trajectory_orientation(
  const TrajectoryPoints & input_trajectory, TrajectoryPoints & output_trajectory,
  const double max_distance_m, const double max_yaw_rad)
{
  for (auto & out_point : output_trajectory) {
    const auto nearest_index_opt = autoware::motion_utils::findNearestIndex(
      input_trajectory, out_point.pose, max_distance_m, max_yaw_rad);
    if (!nearest_index_opt.has_value()) {
      continue;
    }
    const auto nearest_index = nearest_index_opt.value();
    out_point.pose.orientation = input_trajectory.at(nearest_index).pose.orientation;
  }
}

std::optional<size_t> findNearestIndex(
  const T & points, const geometry_msgs::msg::Pose & pose,
  const double max_dist = std::numeric_limits<double>::max(),
  const double max_yaw = std::numeric_limits<double>::max())
{
  try {
    validateNonEmpty(points);
  } catch (const std::exception & e) {
    RCLCPP_DEBUG(get_logger(), "%s", e.what());
    return {};
  }

  const double max_squared_dist = max_dist * max_dist;

  double min_squared_dist = std::numeric_limits<double>::max();
  bool is_nearest_found = false;
  size_t min_idx = 0;

  for (size_t i = 0; i < points.size(); ++i) {
    const auto squared_dist = autoware_utils_geometry::calc_squared_distance2d(points.at(i), pose);
    if (squared_dist > max_squared_dist || squared_dist >= min_squared_dist) {
      continue;
    }

    const auto yaw = autoware_utils_geometry::calc_yaw_deviation(
      autoware_utils_geometry::get_pose(points.at(i)), pose);
    if (std::fabs(yaw) > max_yaw) {
      continue;
    }

    min_squared_dist = squared_dist;
    min_idx = i;
    is_nearest_found = true;
  }

  if (is_nearest_found) {
    return min_idx;
  }
  return std::nullopt;
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

void calculate_time_from_start(
  std::vector<autoware_planning_msgs::msg::TrajectoryPoint> & trajectory,
  const geometry_msgs::msg::Point & current_ego_point, const float min_velocity)
{
  const auto nearest_segment_idx = findNearestSegmentIndex(trajectory, current_ego_point);
  if (nearest_segment_idx + 1 == trajectory.size()) {
    return;
  }
  for (auto & p : trajectory) {
    p.time_from_start = rclcpp::Duration::from_seconds(0);
  }
  // TODO(Maxime): some points can have very low velocities which introduce huge time errors
  // Temporary solution: use a minimum velocity
  for (auto idx = nearest_segment_idx + 1; idx < trajectory.size(); ++idx) {
    const auto & from = trajectory[idx - 1];
    const auto velocity = std::max(min_velocity, from.longitudinal_velocity_mps);
    if (velocity != 0.0) {
      auto & to = trajectory[idx];
      const auto t = autoware_utils_geometry::calc_distance2d(from, to) / velocity;
      to.time_from_start = rclcpp::Duration::from_seconds(t) + from.time_from_start;
    }
  }
}

size_t findNearestSegmentIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  const size_t nearest_idx = findNearestIndex(points, point);

  if (nearest_idx == 0) {
    return 0;
  }
  if (nearest_idx == points.size() - 1) {
    return points.size() - 2;
  }

  const double signed_length = calcLongitudinalOffsetToSegment(points, nearest_idx, point);

  if (signed_length <= 0) {
    return nearest_idx - 1;
  }

  return nearest_idx;
}

[[nodiscard]] size_t findNearestIndex(const T & points, const geometry_msgs::msg::Point & point)
{
  validateNonEmpty(points);

  double min_dist = std::numeric_limits<double>::max();
  size_t min_idx = 0;

  for (size_t i = 0; i < points.size(); ++i) {
    const auto dist = autoware_utils_geometry::calc_squared_distance2d(points.at(i), point);
    if (dist < min_dist) {
      min_dist = dist;
      min_idx = i;
    }
  }
  return min_idx;
}

double calc_squared_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  const auto dx = p1.x - p2.x;
  const auto dy = p1.y - p2.y;
  return dx * dx + dy * dy;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calcLongitudinalOffsetToSegment(
  const T & points, const size_t seg_idx, const geometry_msgs::msg::Point & p_target,
  const bool throw_exception = false)
{
  if (seg_idx >= points.size() - 1) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      ": Failed to calculate longitudinal offset because the given segment index is out of the "
      "points size.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::out_of_range(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return std::nan("");
  }

  const auto overlap_removed_points = removeOverlapPoints(points, seg_idx);

  if (throw_exception) {
    validateNonEmpty(overlap_removed_points);
  } else {
    try {
      validateNonEmpty(overlap_removed_points);
    } catch (const std::exception & e) {
      RCLCPP_DEBUG(get_logger(), "%s", e.what());
      return std::nan("");
    }
  }

  if (seg_idx >= overlap_removed_points.size() - 1) {
    const std::string error_message(
      "[autoware_motion_utils] " + std::string(__func__) +
      ": Longitudinal offset calculation is not supported for the same points.");
    autoware_utils_system::print_backtrace();
    if (throw_exception) {
      throw std::runtime_error(error_message);
    }
    RCLCPP_DEBUG(
      get_logger(),
      "%s Return NaN since no_throw option is enabled. The maintainer must check the code.",
      error_message.c_str());
    return std::nan("");
  }

  const auto p_front = autoware_utils_geometry::get_point(overlap_removed_points.at(seg_idx));
  const auto p_back = autoware_utils_geometry::get_point(overlap_removed_points.at(seg_idx + 1));

  const Eigen::Vector3d segment_vec{p_back.x - p_front.x, p_back.y - p_front.y, 0};
  const Eigen::Vector3d target_vec{p_target.x - p_front.x, p_target.y - p_front.y, 0};

  return segment_vec.dot(target_vec) / segment_vec.norm();
}

[[nodiscard]] T removeOverlapPoints(const T & points, const size_t start_idx = 0)
{
  if (points.size() < start_idx + 1) {
    return points;
  }

  T dst;
  dst.reserve(points.size());

  for (size_t i = 0; i <= start_idx; ++i) {
    dst.push_back(points.at(i));
  }

  constexpr double eps = 1.0E-08;
  for (size_t i = start_idx + 1; i < points.size(); ++i) {
    const auto prev_p = autoware_utils_geometry::get_point(dst.back());
    const auto curr_p = autoware_utils_geometry::get_point(points.at(i));
    if (std::abs(prev_p.x - curr_p.x) < eps && std::abs(prev_p.y - curr_p.y) < eps) {
      continue;
    }
    dst.push_back(points.at(i));
  }

  return dst;
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}

double calc_distance2d(const Point1 & point1, const Point2 & point2)
{
  const auto p1 = get_point(point1);
  const auto p2 = get_point(point2);
  return std::hypot(p1.x - p2.x, p1.y - p2.y);
}

geometry_msgs::msg::Point get_point(const T & p)
{
  return geometry_msgs::build<geometry_msgs::msg::Point>().x(p.x).y(p.y).z(p.z);
}
